#!/usr/bin/env node
/** The command: `trace` and `summary`, each over the log on standard input. */

import { readFileSync } from 'node:fs'
import { LogError, parse, splitLines } from './parse.js'
import { run } from './queue.js'

const USAGE = 'usage: cli.js trace|summary'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const argv = process.argv.slice(2)
const mode = argv[0]
if (!['trace', 'summary'].includes(mode) || argv.length !== 1) fail(USAGE)

const policy = {}
let parsed
try {
  parsed = parse(splitLines(readFileSync(0, 'utf8')), policy)
} catch (error) {
  if (!(error instanceof LogError)) throw error
  fail(error.line === 0 ? error.message : `line ${error.line}: ${error.message}`)
}

const { attempts, end } = run(parsed.jobs, parsed.submissions, policy)
const out = []
if (mode === 'trace') {
  for (const one of attempts) out.push(`${one.start} ${one.id} attempt=${one.attempt} ${one.outcome} finish=${one.finish}`)
} else {
  for (const { id } of [...parsed.submissions].sort((left, right) => (left.id < right.id ? -1 : 1))) {
    const own = attempts.filter(one => one.id === id)
    out.push(`${id} attempts=${own.length} ${own[own.length - 1].outcome}`)
  }
}
out.push(`end ${end}`)
process.stdout.write(out.map(line => `${line}\n`).join(''))

/** The log grammar: the directives, and the failures each one words. */

const ID = /^[A-Za-z0-9_.-]+$/
const DIGITS = /^[0-9]+$/

/** One refusal of an input line, carrying the 1-based line, or 0 when the failure names none. */
export class LogError extends Error {
  /**
   * @param {number} line - the 1-based input line, or 0 when the failure names no line.
   * @param {string} message - the message the specification words, without the position.
   */
  constructor(line, message) {
    super(message)
    this.name = 'LogError'
    this.line = line
  }
}

/**
 * Every input line, with the empty tail a trailing newline leaves dropped.
 * @param {string} text - the whole input.
 * @returns {string[]} the lines.
 */
export function splitLines(text) {
  const split = text.split('\n')
  if (split.length > 0 && split[split.length - 1] === '') split.pop()
  return split
}

/** One field read as a non-negative integer, or the failure that names it. */
function count(line, field, word) {
  if (!DIGITS.test(word)) throw new LogError(line, `${field} must be a non-negative integer`)
  return Number(word)
}

/** One field read as a positive integer, or the failure that names it. */
function positive(line, field, word) {
  const value = count(line, field, word)
  if (value < 1) throw new LogError(line, `${field} must be a positive integer`)
  return value
}

/**
 * Parse the job log.
 * @param {string[]} lines - the input lines.
 * @param {{limit?: {starts: number, window: number}}} policy - the policy the log sets, edited in place.
 * @returns {{jobs: Map<string, {id: string, duration: number, outcomes: string[]}>, submissions: {id: string, at: number}[]}} the declared jobs and the submissions in input order.
 * @throws {LogError} on the first line the grammar refuses.
 */
export function parse(lines, policy) {
  const jobs = new Map()
  const submissions = []
  const submitted = new Map()
  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const text = raw.trim()
    if (text === '' || text.startsWith('#')) continue
    const words = text.split(/\s+/u)
    if (words[0] === 'limit') {
      if (words.length !== 3) throw new LogError(line, 'expected limit <starts> <window>')
      if (policy.limit !== undefined) throw new LogError(line, 'limit is declared twice')
      policy.limit = { starts: positive(line, 'starts', words[1]), window: positive(line, 'window', words[2]) }
    } else if (words[0] === 'job') {
      if (words.length < 4) throw new LogError(line, 'expected job <id> <duration> <outcome>...')
      const id = words[1]
      if (!ID.test(id)) throw new LogError(line, `invalid job id ${id}`)
      if (jobs.has(id)) throw new LogError(line, `job ${id} is declared twice`)
      const duration = count(line, 'duration', words[2])
      for (const outcome of words.slice(3)) {
        if (outcome !== 'ok' && outcome !== 'fail') throw new LogError(line, `invalid outcome ${outcome}`)
      }
      jobs.set(id, { id, duration, outcomes: words.slice(3) })
    } else if (words[0] === 'submit') {
      if (words.length !== 3) throw new LogError(line, 'expected submit <at> <id>')
      const at = count(line, 'at', words[1])
      const id = words[2]
      if (!ID.test(id)) throw new LogError(line, `invalid job id ${id}`)
      if (submitted.has(id)) throw new LogError(line, `job ${id} is submitted twice`)
      submitted.set(id, line)
      submissions.push({ id, at })
    } else {
      throw new LogError(line, `unknown directive ${words[0]}`)
    }
  }
  for (const { id } of submissions) {
    if (!jobs.has(id)) throw new LogError(0, `unknown job ${id}`)
  }
  return { jobs, submissions }
}

/** The simulation: one worker and a rate limit on starts. */

import { createClock } from './clock.js'

/**
 * Run every submission to a verdict.
 * @param {Map<string, {id: string, duration: number, outcomes: string[]}>} jobs - the declared jobs.
 * @param {{id: string, at: number}[]} submissions - the submissions, in input order.
 * @param {{limit?: {starts: number, window: number}}} policy - the rate limit in force.
 * @returns {{attempts: {start: number, id: string, attempt: number, outcome: string, finish: number}[], end: number}} the attempts in the order they started and the clock at the end.
 */
export function run(jobs, submissions, policy) {
  const clock = createClock()
  const queued = submissions.map((submission, order) => ({ ...submission, order, readyAt: submission.at, attempt: 0 }))
  const attempts = []
  const starts = []
  while (queued.length > 0) {
    let pick = 0
    for (const [index, entry] of queued.entries()) {
      const best = queued[pick]
      if (entry.readyAt < best.readyAt || (entry.readyAt === best.readyAt && entry.order < best.order)) pick = index
    }
    const entry = queued.splice(pick, 1)[0]
    clock.advanceTo(entry.readyAt)
    if (policy.limit !== undefined && starts.length >= policy.limit.starts) {
      const oldest = starts[starts.length - policy.limit.starts]
      if (clock.now() - oldest < policy.limit.window) clock.advanceTo(oldest + policy.limit.window)
    }
    const job = jobs.get(entry.id)
    const start = clock.now()
    starts.push(start)
    const attempt = entry.attempt + 1
    const outcome = job.outcomes[Math.min(attempt, job.outcomes.length) - 1]
    const finish = start + job.duration
    clock.advanceTo(finish)
    attempts.push({ start, id: entry.id, attempt, outcome, finish })
  }
  return { attempts, end: clock.now() }
}

/** The clock the simulation runs on: it only ever moves forward, and only when asked. */

/**
 * A clock starting at zero.
 * @returns {{now: () => number, advanceTo: (instant: number) => void}} the clock.
 */
export function createClock() {
  let instant = 0
  return {
    now: () => instant,
    advanceTo: (target) => {
      if (target > instant) instant = target
    },
  }
}

